			unlock = {
				{ type = "quest", id = 6403 },
			},
			text = [=[In the throne room of {link:stormwind-keep}Stormwind Keep{/link}, Windsor laid his proof before the court, and {link:katrana-prestor}Lady Katrana Prestor{/link} cast off her human shape. She was {link:onyxia}Onyxia{/link}, daughter of {link:deathwing}Deathwing{/link}, and for as long as she had counselled the regent the black dragonflight had held the ear of {link:stormwind-city}Stormwind{/link}. Windsor died there. At {link:morgan-s-vigil}the Vigil{/link}, Maxwell understood at last why his pleas had gone unanswered. The dragons had commanded the {link:blackrock-mountain}Blackrock{/link} from the mountain, and they had silenced Stormwind from its own court.]=],
