Add({
	kind = "figure",
	id = "helendis-riverhorn",
	title = "Helendis Riverhorn",
	aliases = { "Helendis" },
	subtitle = "Scout of Morgan's Vigil",
	tier = "B",
	region = "burning-steppes",
	npc = { 9562 },
	allegiance = "Alliance · Morgan's Vigil",
	found = [=[The eastern edge of Morgan's Vigil, above the dragonkin slopes]=],
	pin = { x = 85.8, y = 68.9 },
	unlock = {
		{ type = "interact" },
	},
	hint = [=[Speak with the night elf who watches the dragonkin from the edge of Morgan's Vigil.]=],
	sections = {
		{
			title = "Summary",
			text = [=[Helendis Riverhorn is a {link:night-elves}night elf{/link} who serves at {link:morgan-s-vigil}Morgan's Vigil{/link}. He stands at the edge of the ridge, above the slopes where the black dragonkin gather, and watches them. He calls upon {link:cenarius}Cenarius{/link} when he wishes a soldier well. It was he who first saw clearly what the {link:blackrock-clan}Blackrock orcs{/link} truly were, and who sent that knowledge south to {link:lakeshire}Lakeshire{/link}.]=],
		},
		{
			title = "Significance",
			text = [=[Helendis began the chain of events that would one day reach the throne room of {link:stormwind-city}Stormwind{/link}. The humans had always believed that the {link:blackrock-mountain}Blackrock{/link} were savage by nature. Helendis found that they were driven. The rage that fills them, he wrote, is fed by the black dragonflight, and it is the dragons who are their true masters.]=],
		},
		{
			title = "Deeds",
			text = [=[• He fights the dragonkin who press upon {link:morgan-s-vigil}the Vigil{/link}.
• He writes to {link:magistrate-solomon}Magistrate Solomon{/link} of the true masters of the {link:blackrock-mountain}Blackrock{/link}.
• He tracks the endless packs of Blackrock worgs to their source.]=],
		},
	},
	chapters = {
		{
			key = "dragonkin-below-the-ridge",
			title = "Dragonkin Below the Ridge",
			hint = "Push back the dragonkin beneath Morgan's Vigil.",
			unlock = {
				{ type = "quest", id = 4182 },
			},
			text = [=[Helendis would not speak of grave matters to a stranger. First the stranger had to prove able to stand against dragonkin. Only when broodlings, dragonspawn, wyrmkin and a drake had fallen on the slopes below did he judge the newcomer ready to hear more.]=],
		},
		{
			key = "a-letter-to-lakeshire",
			title = "A Letter to Lakeshire",
			hint = "Carry Helendis's letter south to Lakeshire.",
			unlock = {
				{ type = "quest", id = 4183 },
			},
			text = [=[What Helendis had found in the homeland of the {link:blackrock-mountain}Blackrock{/link} could not stay on one ridge. He sealed a letter to {link:magistrate-solomon}Magistrate Solomon{/link}: the orcs were not their own masters, and it was the black dragonflight that filled them with rage. Solomon wept when he read what it meant for his town, and he sent it on to {link:stormwind-city}Stormwind{/link}.]=],
		},
		{
			key = "the-worg-mother",
			title = "The Worg Mother",
			hint = "Seek the source of the worgs in Blackrock Spire.",
			unlock = {
				{ type = "quest", id = 4701 },
			},
			text = [=[The {link:blackrock-mountain}Blackrock{/link} worgs never grew fewer, however many were slain. Helendis's scouts learned that the beasts were bred and trained in the Spire. He sent a hunter to find the source, and he shouted one name as the hunter left: Halycon. She was a creature of dark magic, and Helendis asked that no one grieve for her.]=],
		},
	},
	mentions = {
		{
			text = "Dragonkin Menace",
			unlock = {
				{ type = "quest", id = 4182 },
			},
		},
		{
			text = "The True Masters",
			unlock = {
				{ type = "quest", id = 4183 },
			},
		},
		{
			text = "Put Her Down",
			unlock = {
				{ type = "quest", id = 4701 },
			},
		},
	},
	bonds = {
