})

Add({
	kind = "figure",
	id = "ragged-john",
	title = "Ragged John",
	subtitle = "Witness of the Mountain",
	tier = "B",
	region = "burning-steppes",
	npc = { 9563 },
	allegiance = "None",
	found = "Flame Crest, beneath the northern ridge",
