			title = "Summary",
			text = [=[Ragged John is a {link:dwarves}dwarf{/link} who lives at {link:flame-crest}Flame Crest{/link}, in the cave beneath the northern ridge, and he is rarely sober. He was at Marshal Windsor's side on the day the marshal vanished. {link:marshal-maxwell}Marshal Maxwell{/link} calls him a coward. John prefers to say that he is a little sloppy, and that dwarves never get drunk.]=],
		},
		{
			title = "Significance",
			text = [=[John is the only witness to Windsor's fate. His tale, however hard it is to follow, told {link:morgan-s-vigil}Morgan's Vigil{/link} that Windsor still lived, and where to look for him.]=],
		},
		{
			title = "Deeds",
			text = [=[• He marched with Marshal Windsor into {link:blackrock-mountain}Blackrock Mountain{/link}.
• He slipped into the shadows when the orcs attacked.
• He goes into Blackrock Spire now and then, and listens to what the orcs say.]=],
		},
	},
	chapters = {
		{
			key = "ragged-john-s-tale",
			title = "Ragged John's Tale",
			hint = "Hear from Ragged John what befell Marshal Windsor.",
			unlock = {
				{ type = "quest", id = 4224 },
			},
			text = [=[John tells it at length. Windsor was in a black mood that day and kept saying that something felt wrong. In the heart of the mountain the {link:blackrock-mountain}Blackrock{/link} fell upon them, and John hid. Windsor stood his ground with Ironfoe, the {link:orcs}orc{/link}-slaying hammer that {link:franclorn-forgewright}Franclorn Forgewright{/link} made for one of his forefathers, and he was still standing, soaked in orc blood, when the fighting stopped. Then came the {link:dark-iron-dwarves}Dark Irons{/link}, in their hundreds. They did not kill him, perhaps because his ancestor had been a friend to their people. They took him prisoner, and their leader took Ironfoe. John never saw him again.]=],
		},
		{
			key = "mother-s-milk",
			title = "Mother's Milk",
			hint = [=[Bring Ragged John a living sample of the Spire's deadliest poison.]=],
			unlock = {
				{ type = "quest", id = 4866 },
			},
			text = [=[In the Spire John heard the orcs speak of a poison they call Mother's Milk, after the great spider Mother Smolderweb. He wanted it, and not from a gland: it had to come fresh, in the veins of someone she had bitten. When he had drawn it out, he explained that it would make his finest ale yet.]=],
		},
	},
	mentions = {
		{
			text = "The True Masters",
			unlock = {
				{ type = "quest", id = 4224 },
			},
		},
		{
			text = "Mother's Milk",
			unlock = {
				{ type = "quest", id = 4866 },
			},
		},
	},
	bonds = {
		{ id = "reginald-windsor", name = "Reginald Windsor", note = "the marshal he marched with" },
		{ id = "marshal-maxwell", name = "Marshal Maxwell", note = "calls him a coward" },
		{ id = "franclorn-forgewright", name = "Franclorn Forgewright", note = "made Windsor's hammer" },
	},
})

